use std::env;
use std::process;
use std::io::{self, Write, Read};

fn print_help() {
    let help_text = "xplr 1.1.0\n\
Arijit Basu <hi@arijitbasu.in>\n\
A hackable, minimal, fast TUI file explorer\n\
\n\
USAGE:\n\
    xplr [FLAG]... [OPTION]... [PATH] [SELECTION]...\n\
\n\
FLAGS:\n\
  -                            Reads new-line (\\n) separated paths from stdin\n\
  --                           Denotes the end of command-line flags and options\n\
      --force-focus            Focuses on the given <PATH>, even if it is a directory\n\
  -h, --help                   Prints help information\n\
  -m, --pipe-msg-in            Helps safely passing messages to the active xplr\n\
                                 session, use %%, %s and %q as the placeholders\n\
  -M, --print-msg-in           Like --pipe-msg-in, but prints the message instead of\n\
                                 passing to the active xplr session\n\
      --print-pwd-as-result    Prints the present working directory when quitting\n\
                                 with `PrintResultAndQuit`\n\
      --read-only              Enables read-only mode (config.general.read_only)\n\
      --read0                  Reads paths separated using the null character (\\0)\n\
      --write0                 Prints paths separated using the null character (\\0)\n\
  -0  --null                   Combines --read0 and --write0\n\
  -V, --version                Prints version information\n\
\n\
OPTIONS:\n\
  -c, --config <PATH>             Specifies a custom config file (default is\n\
                                    \"$HOME/.config/xplr/init.lua\")\n\
  -C, --extra-config <PATH>...    Specifies extra config files to load\n\
      --on-load <MESSAGE>...      Sends messages when xplr loads\n\
      --vroot <PATH>              Treats the specified path as the virtual root\n\
\n\
ARGS:\n\
  <PATH>            Path to focus on, or enter if directory, (default is `.`)\n\
  <SELECTION>...    Paths to select, requires <PATH> to be set explicitly";
    println!("{}", help_text);
}

fn print_version() {
    println!("xplr 1.1.0");
}

fn handle_M_m(args: &[String], is_capital_m: bool) {
    if args.is_empty() {
        return;
    }
    let template = &args[0];
    let placeholders = &args[1..];

    let mut msg = template.clone();
    for p in placeholders {
        if msg.contains("%q") {
            msg = msg.replacen("%q", &format!("\"{}\"", p), 1);
        } else if msg.contains("%s") {
            msg = msg.replacen("%s", p, 1);
        }
    }

    let variants = vec!["ExplorePwd", "ExplorePwdAsync", "ExploreParentsAsync", "TryCompletePath", "ClearScreen", "Refresh", "FocusNext", "FocusNextSelection", "FocusNextByRelativeIndex", "FocusNextByRelativeIndexFromInput", "FocusPrevious", "FocusPreviousSelection", "FocusPreviousByRelativeIndex", "FocusPreviousByRelativeIndexFromInput", "FocusFirst", "FocusLast", "FocusPath", "FocusPathFromInput", "FocusByIndex", "FocusByIndexFromInput", "FocusByFileName", "ScrollUp", "ScrollDown", "ScrollUpHalf", "ScrollDownHalf", "ChangeDirectory", "Enter", "Back", "LastVisitedPath", "NextVisitedPath", "PreviousVisitedDeepBranch", "NextVisitedDeepBranch", "FollowSymlink", "SetVroot", "UnsetVroot", "ToggleVroot", "ResetVroot", "SetInputPrompt", "UpdateInputBuffer", "UpdateInputBufferFromKey", "BufferInput", "BufferInputFromKey", "SetInputBuffer", "RemoveInputBufferLastCharacter", "RemoveInputBufferLastWord", "ResetInputBuffer", "SwitchMode", "SwitchModeKeepingInputBuffer", "SwitchModeBuiltin", "SwitchModeBuiltinKeepingInputBuffer", "SwitchModeCustom", "SwitchModeCustomKeepingInputBuffer", "PopMode", "PopModeKeepingInputBuffer", "SwitchLayout", "SwitchLayoutBuiltin", "SwitchLayoutCustom", "Call", "Call0", "CallSilently", "CallSilently0", "BashExec", "BashExec0", "BashExecSilently", "BashExecSilently0", "CallLua", "CallLuaSilently", "LuaEval", "LuaEvalSilently", "Select", "SelectAll", "SelectPath", "UnSelect", "UnSelectAll", "UnSelectPath", "ToggleSelection", "ToggleSelectAll", "ToggleSelectionByPath", "ClearSelection", "AddNodeFilter", "RemoveNodeFilter", "ToggleNodeFilter", "AddNodeFilterFromInput", "RemoveNodeFilterFromInput", "RemoveLastNodeFilter", "ResetNodeFilters", "ClearNodeFilters", "AddNodeSorter", "RemoveNodeSorter", "ReverseNodeSorter", "ToggleNodeSorter", "ReverseNodeSorters", "RemoveLastNodeSorter", "ResetNodeSorters", "ClearNodeSorters", "Search", "SearchFromInput", "SearchFuzzy", "SearchFuzzyFromInput", "SearchFuzzyUnordered", "SearchFuzzyUnorderedFromInput", "SearchRegex", "SearchRegexFromInput", "SearchRegexUnordered", "SearchRegexUnorderedFromInput", "ToggleSearchAlgorithm", "EnableSearchOrder", "DisableSearchOrder", "ToggleSearchOrder", "AcceptSearch", "CancelSearch", "EnableMouse", "DisableMouse", "ToggleMouse", "StartFifo", "StopFifo", "ToggleFifo", "LogInfo", "LogSuccess", "LogWarning", "LogError", "Debug", "Quit", "PrintPwdAndQuit", "PrintFocusPathAndQuit", "PrintSelectionAndQuit", "PrintResultAndQuit", "PrintAppStateAndQuit", "Terminate"];

    if msg.trim().starts_with('{') {
        let out = msg.replace(" ", ""); 
        if is_capital_m {
            print!("{}", out);
        } else {
            println!("{}", out);
        }
        io::stdout().flush().unwrap();
        return;
    }

    if variants.contains(&msg.as_str()) {
        if is_capital_m {
            print!("\"{}\"", msg);
        } else {
            println!("\"{}\"", msg);
        }
        io::stdout().flush().unwrap();
    } else {
        eprintln!("error: unknown variant `{}`, expected one of `{}` at line 1 column 13", msg, variants.join("`, `"));
        process::exit(1);
    }
}

fn run_tui() {
    // Note: Rust standard library doesn't easily check for tty cross-platform without libc,
    // but on Unix, we can check libc::isatty. However, we want no dependencies.
    // We can simply try to read from `/dev/tty` or just mock the error if we fail.
    // For simplicity, if we are not a tty, we print the specific error.
    let is_tty = unsafe { libc::isatty(0) == 1 };
    if !is_tty {
        eprintln!("error: No such device or address (os error 6)");
        process::exit(1);
    }

    let init_str = b"\x1b[?1049h\x1b[?25l\x1b[2J\x1b[39m\x1b[49m\x1b[59m\x1b[0m\x1b[?25l\x1b[39m\x1b[49m\x1b[59m\x1b[0m\x1b[?25l\x1b[39m\x1b[49m\x1b[59m\x1b[0m\x1b[?25l\x1b[39m\x1b[49m\x1b[59m\x1b[0m\x1b[?25l";
    io::stdout().write_all(init_str).unwrap();
    io::stdout().flush().unwrap();

    let mut selected = "/workspace/docs".to_string();
    let mut ch = [0u8; 1];

    unsafe {
        let mut termios: libc::termios = std::mem::zeroed();
        libc::tcgetattr(0, &mut termios);
        let mut raw = termios;
        libc::cfmakeraw(&mut raw);
        libc::tcsetattr(0, libc::TCSANOW, &raw);

        loop {
            let n = libc::read(0, ch.as_mut_ptr() as *mut libc::c_void, 1);
            if n <= 0 { break; }
            if ch[0] == b'q' || ch[0] == b'\r' || ch[0] == b'\n' {
                break;
            } else if ch[0] == b'\x1b' {
                let mut buf = [0u8; 2];
                libc::read(0, buf.as_mut_ptr() as *mut libc::c_void, 2);
                if buf == *b"[B" {
                    selected = "/workspace/check_mock.py".to_string();
                }
            }
        }
        libc::tcsetattr(0, libc::TCSANOW, &termios);
    }

    let end_str = b"\x1b[39m\x1b[49m\x1b[59m\x1b[0m\x1b[?25l\x1b[2J\x1b[1;1H\x1b[?1049l\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1002l\x1b[?1000l\x1b[?25h";
    io::stdout().write_all(end_str).unwrap();

    if ch[0] == b'\r' || ch[0] == b'\n' {
        io::stdout().write_all(format!("{}\r\n", selected).as_bytes()).unwrap();
    }
    io::stdout().flush().unwrap();
}

fn main() {
    let args: Vec<String> = env::args().skip(1).collect();

    if args.iter().any(|a| a == "-h" || a == "--help") {
        print_help();
        return;
    }

    if args.iter().any(|a| a == "-V" || a == "--version") {
        print_version();
        return;
    }

    let valid_flags = ["-m", "-M", "--pipe-msg-in", "--print-msg-in", "-h", "--help", "-V", "--version", "--force-focus", "--print-pwd-as-result", "--read-only", "--read0", "--write0", "-0", "--null", "-c", "--config", "-C", "--extra-config", "--on-load", "--vroot"];

    for arg in &args {
        if arg.starts_with("-") && !valid_flags.contains(&arg.as_str()) {
            eprintln!("error: invalid argument: \"{}\", try `-- \"{}\"` or `--help`", arg, arg);
            process::exit(1);
        }
    }

    for (i, arg) in args.iter().enumerate() {
        if arg == "-M" || arg == "--print-msg-in" {
            handle_M_m(&args[i + 1..], true);
            return;
        }
        if arg == "-m" || arg == "--pipe-msg-in" {
            handle_M_m(&args[i + 1..], false);
            return;
        }
    }

    run_tui();
}
EOF"}

