#include <unistd.h>

typedef struct {
    char name[256];
    int is_dir;
} FileNode;

int compare_nodes(const void *a, const void *b) {
    FileNode *fa = (FileNode *)a;
    FileNode *fb = (FileNode *)b;
    if (fa->is_dir != fb->is_dir) {
        return fb->is_dir - fa->is_dir; // Directories first
    }
    return strcmp(fa->name, fb->name);
}

void get_nth_file(int n, char *selected) {
    DIR *d = opendir(".");
    if (!d) return;

    FileNode nodes[1024];
    int count = 0;
    struct dirent *dir;

    while ((dir = readdir(d)) != NULL) {
        if (strcmp(dir->d_name, ".") == 0 || strcmp(dir->d_name, "..") == 0) continue;

        struct stat st;
        if (stat(dir->d_name, &st) == 0) {
            strncpy(nodes[count].name, dir->d_name, 255);
            nodes[count].name[255] = '\0';
            nodes[count].is_dir = S_ISDIR(st.st_mode) ? 1 : 0;
            count++;
            if (count >= 1024) break;
        }
    }
    closedir(d);

    if (count > 0) {
        qsort(nodes, count, sizeof(FileNode), compare_nodes);
        if (n >= count) n = count - 1;
        if (n < 0) n = 0;

        char cwd[1024];
        if (getcwd(cwd, sizeof(cwd)) != NULL) {
            if (strcmp(cwd, "/") == 0) {
                snprintf(selected, 256, "/%s", nodes[n].name);
            } else {
                snprintf(selected, 256, "%s/%s", cwd, nodes[n].name);
            }
        }
    }
}
