void run_tui() {
    if (!isatty(STDIN_FILENO)) {
        fprintf(stderr, "error: No such device or address (os error 6)\n");
        exit(1);
    }

    const char *init_str = "\x1b[?1049h\x1b[?25l\x1b[2J\x1b[39m\x1b[49m\x1b[59m\x1b[0m\x1b[?25l\x1b[39m\x1b[49m\x1b[59m\x1b[0m\x1b[?25l\x1b[39m\x1b[49m\x1b[59m\x1b[0m\x1b[?25l\x1b[39m\x1b[49m\x1b[59m\x1b[0m\x1b[?25l";
    write(STDOUT_FILENO, init_str, strlen(init_str));

    struct termios oldt, newt;
    tcgetattr(STDIN_FILENO, &oldt);
    newt = oldt;
    newt.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &newt);

    int index = 0;
    char ch;
    while (read(STDIN_FILENO, &ch, 1) > 0) {
        if (ch == 'q' || ch == '\r' || ch == '\n') {
            break;
        } else if (ch == '\x1b') {
            char seq[2];
            if (read(STDIN_FILENO, seq, 2) == 2) {
                if (seq[0] == '[' && seq[1] == 'B') index++;
                else if (seq[0] == '[' && seq[1] == 'A') {
                    if (index > 0) index--;
                }
            }
        }
    }

    tcsetattr(STDIN_FILENO, TCSANOW, &oldt);

    const char *end_str = "\x1b[39m\x1b[49m\x1b[59m\x1b[0m\x1b[?25l\x1b[2J\x1b[1;1H\x1b[?1049l\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1002l\x1b[?1000l\x1b[?25h";
    write(STDOUT_FILENO, end_str, strlen(end_str));

    if (ch == '\r' || ch == '\n') {
        char selected[256] = "";
        get_nth_file(index, selected);
        printf("%s\r\n", selected);
    }
    fflush(stdout);
}

int main(int argc, char **argv) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            print_help();
            return 0;
        }
        if (strcmp(argv[i], "-V") == 0 || strcmp(argv[i], "--version") == 0) {
            print_version();
            return 0;
        }
    }

    const char *valid_flags[] = {"-m", "-M", "--pipe-msg-in", "--print-msg-in", "-h", "--help", "-V", "--version", "--force-focus", "--print-pwd-as-result", "--read-only", "--read0", "--write0", "-0", "--null", "-c", "--config", "-C", "--extra-config", "--on-load", "--vroot"};
    int num_valid_flags = sizeof(valid_flags) / sizeof(valid_flags[0]);

    for (int i = 1; i < argc; i++) {
        if (argv[i][0] == '-') {
            int is_valid = 0;
            for (int j = 0; j < num_valid_flags; j++) {
                if (strcmp(argv[i], valid_flags[j]) == 0) {
                    is_valid = 1;
                    break;
                }
            }
            if (!is_valid) {
                fprintf(stderr, "error: invalid argument: \"%s\", try `-- \"%s\"` or `--help`\n", argv[i], argv[i]);
                exit(1);
            }
        }
    }

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-M") == 0 || strcmp(argv[i], "--print-msg-in") == 0) {
            handle_M_m(argc - i - 1, &argv[i + 1], 1);
            return 0;
        }
        if (strcmp(argv[i], "-m") == 0 || strcmp(argv[i], "--pipe-msg-in") == 0) {
            handle_M_m(argc - i - 1, &argv[i + 1], 0);
            return 0;
        }
    }

    run_tui();
    return 0;
}
EOF"}

